80	        EventDetailResponse detail = service.getDetail(reported.eventId());
81	        List<String> types = detail.timeline().stream().map(TimelineEntry::type).toList();
82	        assertTrue(types.contains("REPORTED"));
83	        assertTrue(types.contains("CLOSED_NOTAM"));
84	        assertTrue(types.contains("INSPECTION_STARTED"));
85	        assertTrue(types.contains("ASSESSED"));
86	        assertTrue(types.contains("REOPEN_NOTAM"));
87	        assertTrue(types.contains("REOPENED"));
88	    }
