            rs.getLong("id"),
            rs.getString("runway_id"),
            rs.getTimestamp("window_start").toInstant(),
            rs.getTimestamp("window_end").toInstant(),
            rs.getInt("duration_minutes"),
            rs.getInt("calendar_version"),
            RoutinePlanStatus.valueOf(rs.getString("status")),
            rs.getString("evidence"),
            (Integer) rs.getObject("slot_flag"),
            (Long) rs.getObject("emergency_event_id"),
            rs.getTimestamp("started_at") == null ? null : rs.getTimestamp("started_at").toInstant(),
            rs.getTimestamp("completed_at") == null ? null : rs.getTimestamp("completed_at").toInstant(),
            rs.getTimestamp("preempted_at") == null ? null : rs.getTimestamp("preempted_at").toInstant(),
            rs.getString("request_id"),
            rs.getTimestamp("created_at").toInstant(),
            rs.getTimestamp("updated_at").toInstant());

    private final JdbcTemplate jdbc;

    public RoutinePlanRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** 插入计划；slotFlag=1 时占用“同跑道同窗唯一获准”唯一索引。 */
    public RoutinePlan insert(RoutinePlan plan) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(connection -> {
            PreparedStatement ps = connection.prepareStatement(
                    "INSERT INTO routine_plan (runway_id, window_start, window_end, duration_minutes,"
                            + " calendar_version, status, evidence, slot_flag, emergency_event_id, started_at,"
                            + " completed_at, preempted_at, request_id, created_at, updated_at)"
                            + " VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, plan.runwayId());
            ps.setTimestamp(2, Timestamp.from(plan.windowStart()));
            ps.setTimestamp(3, Timestamp.from(plan.windowEnd()));
            ps.setInt(4, plan.durationMinutes());
            ps.setInt(5, plan.calendarVersion());
            ps.setString(6, plan.status().name());
            ps.setString(7, plan.evidence());
            if (plan.slotFlag() == null) {
                ps.setNull(8, Types.TINYINT);
            } else {
                ps.setInt(8, plan.slotFlag());
            }
            if (plan.emergencyEventId() == null) {
                ps.setNull(9, Types.BIGINT);
            } else {
                ps.setLong(9, plan.emergencyEventId());
            }
            ps.setTimestamp(10, plan.startedAt() == null ? null : Timestamp.from(plan.startedAt()));
            ps.setTimestamp(11, plan.completedAt() == null ? null : Timestamp.from(plan.completedAt()));
            ps.setTimestamp(12, plan.preemptedAt() == null ? null : Timestamp.from(plan.preemptedAt()));
            ps.setString(13, plan.requestId());
            ps.setTimestamp(14, Timestamp.from(plan.createdAt()));
            ps.setTimestamp(15, Timestamp.from(plan.updatedAt()));
            return ps;
        }, keyHolder);
        long id = Optional.ofNullable(keyHolder.getKey()).orElseThrow().longValue();
        return findById(id).orElseThrow();
    }

    public Optional<RoutinePlan> findById(long id) {
        List<RoutinePlan> rows = jdbc.query("SELECT * FROM routine_plan WHERE id = ?", MAPPER, id);
        return rows.stream().findFirst();
    }

    /** 行级锁定取计划，供状态条件更新串行化。 */
    public Optional<RoutinePlan> findByIdForUpdate(long id) {
        List<RoutinePlan> rows = jdbc.query("SELECT * FROM routine_plan WHERE id = ? FOR UPDATE", MAPPER, id);
        return rows.stream().findFirst();
    }

    /** 取同跑道同窗、且仍占用唯一获准位（slot_flag=1）的计划。 */
    public List<RoutinePlan> findSlotHolders(String runwayId, Instant windowStart, Instant windowEnd) {
        return jdbc.query(
                "SELECT * FROM routine_plan WHERE runway_id = ? AND window_start = ? AND window_end = ?"
                        + " AND slot_flag = 1",
                MAPPER, runwayId, Timestamp.from(windowStart), Timestamp.from(windowEnd));
    }

    /**
     * 条件状态更新（CAS）：仅当当前状态在 expectedStatuses 中才更新；返回受影响行数（1=成功，0=状态已变）。
     * 终态同时释放唯一获准位（slot_flag 置 NULL）。
     */
    public int compareAndUpdate(long id, List<RoutinePlanStatus> expectedStatuses, RoutinePlanStatus newStatus,
                                boolean terminal, Instant startedAt, Instant completedAt, Instant preemptedAt,
                                Long emergencyEventId, Instant updatedAt) {
        String placeholders = expectedStatuses.stream().map(s -> "?").reduce((a, b) -> a + "," + b).orElse("");
        String sql = "UPDATE routine_plan SET status = ?, slot_flag = CASE WHEN ? THEN NULL ELSE 1 END,"
                + " started_at = COALESCE(?, started_at), completed_at = COALESCE(?, completed_at),"
                + " preempted_at = COALESCE(?, preempted_at),"
                + " emergency_event_id = COALESCE(?, emergency_event_id), updated_at = ?"
                + " WHERE id = ? AND status IN (" + placeholders + ")";
        Object[] args = new Object[9 + expectedStatuses.size()];
        args[0] = newStatus.name();
        args[1] = terminal;
        args[2] = startedAt == null ? null : Timestamp.from(startedAt);
        args[3] = completedAt == null ? null : Timestamp.from(completedAt);
        args[4] = preemptedAt == null ? null : Timestamp.from(preemptedAt);
        args[5] = emergencyEventId;
        args[6] = Timestamp.from(updatedAt);
        args[7] = id;
        for (int i = 0; i < expectedStatuses.size(); i++) {
            args[8 + i] = expectedStatuses.get(i).name();
        }
        return jdbc.update(sql, args);
    }

    /** 仅把未开始（获准）计划标记为待重审：日历版本落后且尚未开始。返回受影响行数。 */
    public int markApprovedStaleForReview(int oldVersion, int newVersion, Instant updatedAt) {
        return jdbc.update("UPDATE routine_plan SET status = 'NEEDS_REVIEW', calendar_version = ?,"
                        + " updated_at = ? WHERE status = 'APPROVED' AND calendar_version <= ?",
                newVersion, Timestamp.from(updatedAt), oldVersion);
    }

    /** 同跑道在指定时刻处于未终态（slot_flag=1）的计划，供紧急关闭抢占与开始校验。 */
    public List<RoutinePlan> findActiveByRunway(String runwayId) {
        return jdbc.query("SELECT * FROM routine_plan WHERE runway_id = ? AND slot_flag = 1 ORDER BY id",
                MAPPER, runwayId);
    }

    /** 重审：依据最新日历重新判定，更新冻结版本与证据（保持未终态占用）。 */
    public int updateReview(long id, int calendarVersion, String evidence, RoutinePlanStatus status,
                            Instant updatedAt) {
        return jdbc.update("UPDATE routine_plan SET calendar_version = ?, evidence = ?, status = ?,"
                + " slot_flag = 1, updated_at = ? WHERE id = ? AND status = 'NEEDS_REVIEW'",
                calendarVersion, evidence, status.name(), Timestamp.from(updatedAt), id);
    }
}

